1	// Test helpers: spawn server.mjs as a child process, talk HTTP to it, clean up after.
2	import { spawn } from 'node:child_process';
3	import { mkdtemp, rm } from 'node:fs/promises';
4	import http from 'node:http';
5	import net from 'node:net';
6	import os from 'node:os';
7	import path from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	
10	export const SERVER_PATH = fileURLToPath(new URL('../../server.mjs', import.meta.url));
11	const START_TIMEOUT_MS = 5000;
12	const STRIPPED_ENV = ['PORT', 'DATA_FILE', 'NODE_TEST_CONTEXT', 'NODE_OPTIONS'];
13	
14	function baseEnv(extra) {
15	  const env = { ...process.env };
16	  for (const key of STRIPPED_ENV) delete env[key];
17	  for (const [key, value] of Object.entries(extra)) {
18	    if (value === undefined) delete env[key];
19	    else env[key] = value;
20	  }
21	  return env;
22	}
23	
24	/** Creates a fresh temp folder; returns its path. Remove it with removeDir. */
25	export function makeTempDir() {
26	  return mkdtemp(path.join(os.tmpdir(), 'booking-test-'));
27	}
28	
29	export function removeDir(dir) {
30	  return rm(dir, { recursive: true, force: true });
31	}
32	
33	function spawnServer({ env = {}, cwd }) {
34	  const child = spawn(process.execPath, [SERVER_PATH], {
35	    cwd, env: baseEnv(env), stdio: ['ignore', 'pipe', 'pipe'],
36	  });
37	  const output = { stdout: '', stderr: '' };
38	  child.stdout.setEncoding('utf8').on('data', (s) => { output.stdout += s; });
39	  child.stderr.setEncoding('utf8').on('data', (s) => { output.stderr += s; });
40	  const exited = new Promise((resolve) => {
41	    child.on('close', (code, signal) => resolve({ code, signal }));
42	  });
43	  return { child, output, exited };
44	}
45	
46	/** Runs the server expecting it to exit by itself; resolves { code, stdout, stderr }. */
47	export async function runToExit({ env = {}, cwd, timeoutMs = START_TIMEOUT_MS }) {
48	  const { child, output, exited } = spawnServer({ env, cwd });
49	  const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
50	  const { code, signal } = await exited;
51	  clearTimeout(timer);
52	  return { code, signal, stdout: output.stdout, stderr: output.stderr };
53	}
54	
55	/**
56	 * Starts the server and waits for its "listening" line.
57	 * Resolves { port, output, stop() }; stop() kills it and resolves { code, signal }.
58	 * Rejects (after killing the child) when the server exits or stays silent.
59	 */
60	export async function startServer({ env = {}, cwd } = {}) {
61	  const proc = spawnServer({ env: { PORT: '0', ...env }, cwd });
62	  const stop = async () => {
63	    if (proc.child.exitCode === null && proc.child.signalCode === null) proc.child.kill('SIGKILL');
64	    return proc.exited;
65	  };
66	  try {
67	    const port = await waitForListening(proc);
68	    return { port, output: proc.output, stop, exited: proc.exited };
69	  } catch (err) {
70	    await stop();
71	    throw err;
72	  }
73	}
74	
75	function waitForListening({ child, output, exited }) {
76	  return new Promise((resolve, reject) => {
77	    const timer = setTimeout(() => reject(new Error(`server did not start: ${output.stderr}`)), START_TIMEOUT_MS);
78	    const onData = () => {
79	      const match = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n/.exec(output.stdout);
80	      if (!match) return;
81	      clearTimeout(timer);
82	      child.stdout.off('data', onData);
83	      resolve(Number(match[1]));
84	    };
85	    child.stdout.on('data', onData);
86	    exited.then(({ code }) => {
87	      clearTimeout(timer);
88	      reject(new Error(`server exited with ${code}: ${output.stderr}`));
89	    });
90	  });
91	}
92	
93	/**
94	 * Sends one HTTP request with the path exactly as given (no normalisation).
95	 * Resolves { status, headers, body: Buffer, text, json() }.
96	 */
97	export function request(port, { method = 'GET', path: target = '/', headers = {}, body } = {}) {
98	  return new Promise((resolve, reject) => {
99	    const req = http.request({ host: '127.0.0.1', port, method, path: target, headers, agent: false }, (res) => {
100	      const chunks = [];
101	      res.on('data', (c) => chunks.push(c));
102	      res.on('error', reject);
103	      res.on('end', () => {
104	        const buffer = Buffer.concat(chunks);
105	        const text = buffer.toString('utf8');
106	        resolve({ status: res.statusCode, headers: res.headers, body: buffer, text, json: () => JSON.parse(text) });
107	      });
108	    });
109	    req.on('error', reject);
110	    req.end(body);
111	  });
112	}
113	
114	/** Sends a POST /api/bookings with a JSON content type; `body` may be an object, string or Buffer. */
115	export function postBooking(port, body, headers = { 'Content-Type': 'application/json' }) {
116	  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
117	  return request(port, { method: 'POST', path: '/api/bookings', headers, body: payload });
118	}
119	
120	/**
121	 * Writes raw bytes to the server and resolves with everything it sends until it closes.
122	 * The socket is not half-closed (Node drops replies to half-closed requests that answer
123	 * asynchronously), so the data must end with a request carrying `Connection: close`.
124	 */
125	export function rawRequest(port, data, timeoutMs = START_TIMEOUT_MS) {
126	  return new Promise((resolve, reject) => {
127	    const socket = net.connect(port, '127.0.0.1');
128	    const chunks = [];
129	    const timer = setTimeout(() => {
130	      socket.destroy();
131	      resolve(Buffer.concat(chunks).toString('latin1'));
132	    }, timeoutMs);
133	    socket.on('data', (c) => chunks.push(c));
134	    socket.on('error', (err) => { clearTimeout(timer); reject(err); });
135	    socket.on('close', () => { clearTimeout(timer); resolve(Buffer.concat(chunks).toString('latin1')); });
136	    socket.write(data);
137	  });
138	}
139	
140	/**
141	 * Starts one server in a fresh temp folder for a suite.
142	 * Returns an object whose fields (`port`, `dir`, `dataFile`, `server`) are filled by `before`.
143	 * Usage: const ctx = useServer({ before, after });
144	 */
145	export function useServer({ before, after }, { dataFileName = 'data.json', env = {} } = {}) {
146	  const ctx = { port: 0, dir: '', dataFile: '', server: null };
147	  before(async () => {
148	    ctx.dir = await makeTempDir();
149	    ctx.dataFile = path.join(ctx.dir, dataFileName);
150	    ctx.server = await startServer({ env: { DATA_FILE: ctx.dataFile, ...env }, cwd: ctx.dir });
151	    ctx.port = ctx.server.port;
152	  });
153	  after(async () => {
154	    if (ctx.server) await ctx.server.stop();
155	    if (ctx.dir) await removeDir(ctx.dir);
156	  });
157	  return ctx;
158	}
159	
160	export const VALID_BOOKING = Object.freeze({
161	  room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00',
162	});
