1	// Tiny HTML tokenizer for structural tests. Not a general-purpose parser.
2	const VOID = new Set(['meta', 'link', 'input', 'br', 'img', 'hr']);
3	const RAW = new Set(['script', 'style']);
4	const ENTITIES = [['&lt;', '<'], ['&gt;', '>'], ['&quot;', '"'], ['&#39;', "'"], ['&amp;', '&']];
5	
6	function decode(text) {
7	  return ENTITIES.reduce((acc, [from, to]) => acc.split(from).join(to), text);
8	}
9	
10	function toText(html) {
11	  const stripped = html
12	    .replace(/<!--[\s\S]*?-->/g, '')
13	    .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '')
14	    .replace(/<[^>]*>/g, '');
15	  return decode(stripped).trim();
16	}
17	
18	function parseAttrs(source) {
19	  const attrs = new Map();
20	  const re = /([^\s"'<>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
21	  for (const m of source.matchAll(re)) {
22	    attrs.set(m[1].toLowerCase(), decode(m[2] ?? m[3] ?? m[4] ?? ''));
23	  }
24	  return attrs;
25	}
26	
27	// Index of the '>' ending a start tag that begins at `from`, honouring quotes.
28	function tagEnd(text, from) {
29	  let quote = '';
30	  for (let i = from; i < text.length; i += 1) {
31	    const c = text[i];
32	    if (quote) {
33	      if (c === quote) quote = '';
34	    } else if (c === '"' || c === "'") quote = c;
35	    else if (c === '>') return i;
36	  }
37	  return text.length - 1;
38	}
39	
40	function close(text, node, innerEnd, end) {
41	  node.innerHtml = text.slice(node.innerStart, innerEnd);
42	  node.innerText = toText(node.innerHtml);
43	  node.end = end;
44	}
45	
46	function skipMarkup(text, i) {
47	  if (text.startsWith('<!--', i)) {
48	    const e = text.indexOf('-->', i + 4);
49	    return e < 0 ? text.length : e + 3;
50	  }
51	  return tagEnd(text, i) + 1;
52	}
53	
54	export function parseHtml(text) {
55	  const nodes = [];
56	  const stack = [];
57	  let i = 0;
58	  while (i < text.length) {
59	    const lt = text.indexOf('<', i);
60	    if (lt < 0) break;
61	    if (text.startsWith('<!', lt)) { i = skipMarkup(text, lt); continue; }
62	    if (text[lt + 1] === '/') {
63	      const gt = text.indexOf('>', lt);
64	      const name = text.slice(lt + 2, gt < 0 ? text.length : gt).trim().toLowerCase();
65	      const at = stack.map((n) => n.tag).lastIndexOf(name);
66	      i = (gt < 0 ? text.length : gt) + 1;
67	      if (at < 0) continue;
68	      while (stack.length > at + 1) close(text, stack.pop(), lt, lt);
69	      close(text, stack.pop(), lt, i);
70	      continue;
71	    }
72	    const m = /^<([a-zA-Z][^\s/>]*)/.exec(text.slice(lt, lt + 64));
73	    if (!m) { i = lt + 1; continue; }
74	    const gt = tagEnd(text, lt);
75	    const tag = m[1].toLowerCase();
76	    const node = {
77	      tag, attrs: parseAttrs(text.slice(lt + m[0].length, gt)), start: lt, end: gt + 1,
78	      innerStart: gt + 1, innerText: '', innerHtml: '', children: [],
79	      parentTags: stack.map((n) => n.tag),
80	    };
81	    stack.at(-1)?.children.push(node);
82	    nodes.push(node);
83	    i = gt + 1;
84	    if (VOID.has(tag) || text[gt - 1] === '/') continue;
85	    if (RAW.has(tag)) {
86	      const e = text.toLowerCase().indexOf(`</${tag}`, i);
87	      const rawEnd = e < 0 ? text.length : e;
88	      i = e < 0 ? text.length : tagEnd(text, e) + 1;
89	      close(text, node, rawEnd, i);
90	      node.innerText = '';
91	    } else stack.push(node);
92	  }
93	  while (stack.length) close(text, stack.pop(), text.length, text.length);
94	  return nodes;
95	}
96	
97	export const byId = (nodes, id) => nodes.filter((n) => n.attrs.get('id') === id);
98	export const byTag = (nodes, tag) => nodes.filter((n) => n.tag === tag);
99	export const within = (outer, inner) =>
100	  inner !== outer && inner.start >= outer.start && inner.end <= outer.end;
