1	import { test, describe } from 'node:test';
2	import assert from 'node:assert/strict';
3	import fs from 'node:fs/promises';
4	import net from 'node:net';
5	import path from 'node:path';
6	import {
7	  makeTempDir, removeDir, runToExit, startServer, request, postBooking, VALID_BOOKING,
8	} from './helpers/server.mjs';
9	
10	const PROJECT_ROOT = path.resolve(import.meta.dirname, '..');
11	const FIXTURE_BOOKING = {
12	  id: 2, room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00',
13	};
14	const FIXTURE = '{"nextId":3,"bookings":[{"id":2,"room":"Aurora","title":"Standup","date":"2026-11-03","start":"09:00","end":"10:00"}]}';
15	
16	async function withTemp(fn) {
17	  const dir = await makeTempDir();
18	  try {
19	    return await fn(dir);
20	  } finally {
21	    await removeDir(dir);
22	  }
23	}
24	
25	async function withServer(opts, fn) {
26	  const server = await startServer(opts);
27	  try {
28	    return await fn(server);
29	  } finally {
30	    await server.stop();
31	  }
32	}
33	
34	function listen(port) {
35	  return new Promise((resolve, reject) => {
36	    const srv = net.createServer();
37	    srv.once('error', reject);
38	    srv.listen(port, '127.0.0.1', () => resolve(srv));
39	  });
40	}
41	
42	const closeServer = (srv) => new Promise((resolve) => srv.close(resolve));
43	
44	async function withHeldPort(fn) {
45	  const holder = await listen(0);
46	  try {
47	    return await fn(holder.address().port);
48	  } finally {
49	    await closeServer(holder);
50	  }
51	}
52	
53	function assertOneLineError(result) {
54	  assert.equal(result.code, 1);
55	  assert.equal(result.stdout, '');
56	  assert.match(result.stderr, /^[^\n]+\n$/);
57	  assert.equal(result.stderr.includes('\n    at '), false);
58	  assert.equal(result.stderr.includes('Error:'), false);
59	}
60	
61	async function exists(file) {
62	  try {
63	    await fs.stat(file);
64	    return true;
65	  } catch (err) {
66	    if (err.code === 'ENOENT') return false;
67	    throw err;
68	  }
69	}
