72	  const values = ['abc', '65536', '+1', '-1', ' 80', '80 ', '1e3', '0x10', '8080a', '99999999999999999999', '٣'];
73	  for (const value of values) {
74	    test(`PORT=${JSON.stringify(value)} exits 1 with one stderr line`, async () => {
75	      await withTemp(async (dir) => {
76	        assertOneLineError(await runToExit({ env: { PORT: value }, cwd: dir }));
77	      });
