81	  test('PORT is checked before the data file', async () => {
82	    await withTemp(async (dir) => {
83	      const result = await runToExit({ env: { PORT: 'abc', DATA_FILE: dir }, cwd: dir });
84	      assertOneLineError(result);
85	      assert.notEqual(result.stderr, `cannot read data file ${dir}\n`);
