91	describe('listening', () => {
92	  test('PORT=0 prints the bound port and serves', async () => {
93	    await withTemp(async (dir) => {
94	      const server = await startServer({ env: { PORT: '0' }, cwd: dir });
95	      try {
96	        assert.equal(server.output.stdout, `listening on http://127.0.0.1:${server.port}\n`);
97	        assert.ok(server.port > 0);
98	        assert.equal((await request(server.port, { path: '/api/rooms' })).status, 200);
99	      } finally {
100	        await server.stop();
101	      }
102	      assert.equal(server.output.stdout, `listening on http://127.0.0.1:${server.port}\n`);
103	      assert.equal(server.output.stderr, '');
104	    });
105	  });
106	
107	  test('PORT with leading zeros is accepted', async () => {
108	    await withTemp(async (dir) => {
109	      const probe = await listen(0);
110	      const port = probe.address().port;
111	      await closeServer(probe);
112	      await withServer({ env: { PORT: `0${port}` }, cwd: dir }, async (server) => {
113	        assert.equal(server.port, port);
