253	const withoutRoom = (() => { const { room, ...rest } = FIXTURE_BOOKING; return rest; })();
254	
255	const BAD_DATA = [
256	  ['absolute directory', dirCase('adirabs', true)],
257	  ['relative directory', dirCase('adir', false)],
258	  ['non-ASCII directory name', dirCase('données.json', false)],
259	  ['default name is a directory (unset)', async (dir) => {
260	    await fs.mkdir(path.join(dir, 'bookings.json'));
261	    return { dataFile: undefined, name: 'bookings.json' };
262	  }],
263	  ['default name is a directory (empty)', async (dir) => {
264	    await fs.mkdir(path.join(dir, 'bookings.json'));
