266	  }],
267	  ['empty file', fileCase('')],
268	  ['whitespace-only file', fileCase(' \n\t ')],
269	  ['open brace', fileCase('{')],
270	  ['null', fileCase('null')],
271	  ['empty array', fileCase('[]')],
