15	  const day = (n % 28) + 1;
16	  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
17	}
18	
19	function fields(extra = {}) {
20	  return { room: 'Aurora', title: 'Standup', date: uniqueDate(), start: '09:00', end: '10:00', ...extra };
21	}
22	
23	/** JSON text of a booking padded with trailing spaces to exactly `size` bytes. */
24	function paddedBody(size, extra = {}) {
25	  const text = JSON.stringify(fields(extra));
26	  const padding = size - Buffer.byteLength(text);
27	  assert.ok(padding >= 0, 'fixture larger than requested size');
28	  return text + ' '.repeat(padding);
29	}
