31	/** Raw POST /api/bookings bytes with an explicit Content-Type header line (string or Buffer). */
32	function rawPost(contentTypeLine, body, extraHeaders = '') {
33	  const payload = Buffer.isBuffer(body) ? body : Buffer.from(body, 'utf8');
34	  const head = Buffer.concat([
35	    Buffer.from('POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: ', 'latin1'),
36	    Buffer.isBuffer(contentTypeLine) ? contentTypeLine : Buffer.from(contentTypeLine, 'latin1'),
37	    Buffer.from(`\r\nContent-Length: ${payload.length}\r\n${extraHeaders}Connection: close\r\n\r\n`, 'latin1'),
38	  ]);
39	  return Buffer.concat([head, payload]);
40	}
41	
42	function chunkedPost(body, pieces) {
43	  const buf = Buffer.from(body, 'utf8');
44	  const size = Math.ceil(buf.length / pieces);
45	  const parts = [Buffer.from(
46	    'POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\n'
47	    + 'Transfer-Encoding: chunked\r\nConnection: close\r\n\r\n', 'latin1')];
48	  for (let i = 0; i < buf.length; i += size) {
49	    const piece = buf.subarray(i, i + size);
50	    parts.push(Buffer.from(`${piece.length.toString(16)}\r\n`), piece, Buffer.from('\r\n'));
51	  }
52	  parts.push(Buffer.from('0\r\n\r\n'));
53	  return Buffer.concat(parts);
54	}
55	
56	function statusOf(raw) {
57	  return Number(/^HTTP\/1\.1 (\d{3})/.exec(raw)?.[1]);
58	}
59	
60	function bodyOf(raw) {
61	  const text = raw.slice(raw.indexOf('\r\n\r\n') + 4);
62	  return JSON.parse(text.slice(text.indexOf('{')));
63	}
