1	// Lists running `node .../server.mjs` processes with their cwd and age (testing section tool).
2	import { readdirSync, readFileSync, readlinkSync, statSync } from 'node:fs';
3	
4	const rows = [];
5	for (const pid of readdirSync('/proc').filter((d) => /^\d+$/.test(d))) {
6	  try {
7	    const cmd = readFileSync(`/proc/${pid}/cmdline`, 'utf8').split('\0').join(' ').trim();
8	    if (!/^node .*server\.mjs$/.test(cmd) && !/\/node .*server\.mjs$/.test(cmd)) continue;
9	    const env = readFileSync(`/proc/${pid}/environ`, 'utf8').split('\0').filter((l) => /^(PORT|DATA_FILE)=/.test(l));
10	    const ageS = Math.round((Date.now() - statSync(`/proc/${pid}`).mtimeMs) / 1000);
11	    rows.push({ pid, cmd, cwd: readlinkSync(`/proc/${pid}/cwd`), env, ageS });
12	  } catch {
13	    // process vanished or is not ours to read
14	  }
15	}
16	process.stdout.write(`${JSON.stringify(rows, null, 1)}\n`);
